(N'מבא',N'1-פויינטרים 6',N'פויינטרים 6',N'אוגר נתונים לטמפרטורה ולחות',N'מד טמפ'' ולחות משולב',N'',N'כיולי חוץ י.ג',N'',N'',N'',N'',N'0',N'',N'',N'',N'2026-04-27 00:00:00',N'טמפרטורה ולחות',N'',N'טמפ''',N'סגול'),
(N'מבא',N'1-פויינטרים 7',N'פויינטרים 7',N'אוגר נתונים לטמפרטורה ולחות',N'מד טמפ'' ולחות משולב',N'',N'כיולי חוץ ל.ש',N'',N'',N'',N'',N'0',N'',N'',N'',N'2026-05-27 00:00:00',N'טמפרטורה ולחות',N'',N'טמפ''',N'חום'),
(N'מבא',N'1-פויינטרים 8',N'פויינטרים 8',N'אוגר נתונים לטמפרטורה ולחות',N'מד טמפ'' ולחות משולב',N'',N'כיולי חוץ א.א',N'',N'',N'',N'',N'0',N'',N'',N'',N'2026-05-27 00:00:00',N'טמפרטורה ולחות',N'',N'טמפ''',N'ורוד')
) AS v([Company], [DeviceNumber], [ID], [DeviceDescription], [ProductDescription], [ManufacturerSerialNumber], [DeviceLocation], [Calibrator], [Manufacturer], [Model], [Status], [CalibrationIntervalMonths], [MabaSKU], [DeviceRange], [LastCalibrationReport], [NextCalibrationDate], [Department], [Subdepartment], [DisplayInArrangement], [Notes]);

/*Insert data for measurment devices for temperature and humidity*/

DECLARE @SensorId INT, @LoggerId INT, @MainCategoryId INT

SELECT @SensorId = Id
FROM [dbo].[MeasurementDevicesMainClasses]
WHERE NameEnglish='Sensor'

SELECT @LoggerId = Id
FROM [dbo].[MeasurementDevicesMainClasses]
WHERE NameEnglish='Data logger'


SELECT @MainCategoryId = ID
FROM [dbo].[MainCategories] 
WHERE MainCategoryName = N'טמפרטורה ולחות'

INSERT INTO [dbo].[MeasurementDevices]
           ([MabaID]
           ,[Description]
           ,[Model]
           ,[SerialNumber]
           ,[NextCalibration]
           ,[Note]
           ,[CalibrationDate]
           ,[MeasurementId]
           ,[MainClassId]
           ,[SubClassId]
           ,[MainCategoryId]
           ,[UnitId]
           ,[CalibratorId]
           ,[UpdateUserID]
           ,[MeasurementDeviceStatusId]
           ,[IP]
           ,[Connection]
           ,[SecondaryCategoryId]
           ,[SourceId]
           ,[DeviceLocation]
           ,[MabaSKU]
           ,[DeviceRange]
           ,[LastCalibrationReport]
           ,[DisplayToCoordinator]
		   ,[Manufacturer]
		   )
SELECT t.[ID] AS [MabaID]
	,t.DeviceDescription AS [Description]
	,t.[Model] AS [Model]
	,t.[ManufacturerSerialNumber] AS [SerialNumber]
	,TRY_CAST(t.NextCalibrationDate AS DATETIME2(0)) AS [NextCalibration]
	,t.[Notes] AS [Note]
	,DATEADD(MONTH,TRY_CAST([CalibrationIntervalMonths] AS INT)*-1,TRY_CAST([NextCalibrationDate] as DATE))AS [CalibrationDate]
	,NULL AS [MeasurementId]
	,CASE 
		WHEN t.Subdepartment IN (
				N'2W'
				,'4W'
				)
			THEN @SensorId
		WHEN t.Subdepartment IN (
				N'אוגר LAN'
				,N'אוגר USB'
				,N'אוגר אלחוטי'
				)
			THEN @LoggerId
		ELSE NULL
		END AS [MainClassId]
	,NULL AS [SubClassId]
	,@MainCategoryId AS [MainCategoryId]
	,NULL AS [UnitId]
	,NULL AS [CalibratorId]
	,0 AS [UpdateUserID]
	,CASE 
		WHEN TRY_CAST(t.NextCalibrationDate AS DATETIME2(0)) <= GETDATE()
			THEN (
					SELECT TOP 1 s.StatusId
					FROM [Calibrator].[dbo].[Statuses] AS s
					JOIN [Calibrator].[dbo].[StatusesCategories] AS sc ON s.StatusCategoryId = sc.StatusCategoryId
					WHERE sc.StatusDescriptionENG = N'MeasurementDeviceStatus'
						AND s.StatusDescriptionENG = N'NotCalibrated'
					)
		ELSE (
				SELECT TOP 1 s.StatusId
				FROM [Calibrator].[dbo].[Statuses] AS s
				JOIN [Calibrator].[dbo].[StatusesCategories] AS sc ON s.StatusCategoryId = sc.StatusCategoryId
				WHERE sc.StatusDescriptionENG = N'MeasurementDeviceStatus'
					AND s.StatusDescriptionENG = N'Available'
				)
		END AS [MeasurementDeviceStatusId]
	,NULL AS [IP]
	,CASE 
		WHEN t.Subdepartment IN (
				N'2W'
				,'4W'
				)
			THEN t.Subdepartment
		ELSE NULL
		END AS [Connection]
	,NULL AS [SecondaryCategoryId]
	,1 AS [SourceId]
	,t.[DeviceLocation] AS [DeviceLocation]
	,t.[MabaSKU] AS [MabaSKU]
	,t.[DeviceRange] AS [DeviceRange]
	,t.[LastCalibrationReport] AS [LastCalibrationReport]
	,IIF(LEN([DisplayInArrangement]) > 0, 1, 0) AS [DisplayToCoordinator] 
	,t.[Manufacturer]
FROM #test AS t
LEFT JOIN [dbo].[MeasurementDevices] AS md ON t.[ID] = md.MabaID
WHERE t.[Department] = N'טמפרטורה ולחות' AND md.MabaID IS NULL

UPDATE [dbo].[MeasurementDevices]
SET SerialNumber = REVERSE(SerialNumber)
WHERE  PATINDEX(N'%[' + NCHAR(0x0590) + N'-' + NCHAR(0x05FF) + N']%', SerialNumber COLLATE Latin1_General_100_BIN2) > 0

